UPDATE visitas v 
INNER JOIN notificaciones n ON v.notificacion_id = n.id 
SET v.foto_url = 'https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/1hfcSKizDmCWbiikjxDb/pub/kIKQq7VIRcebWgaMk18Z.jpg', v.observaciones = 'Vecino me informan que el destinatario hace muchos años vivió vendió toda la propiedad y en lo que era la propiedad del mismo existen construida aproximadamente siete viviendas por lo que procedo a dejar en la casa que menos complicación tuve Por cuánto es un barrio sumamente peligroso y hay la presencia de varios masculinos en estado de ebriedad y drogados este dando vuelta amenazándome por lo que procedo a dejar en el primer lugar que forma parte del inmueble donde vivía antes la destinatario' 
WHERE n.glide_id_cedula = 'ba84f51d-4720-4784-998d-f5c4ad4276ff' AND DATE(v.fecha) = DATE('2025-11-05 17:08:52');
UPDATE visitas v 
INNER JOIN notificaciones n ON v.notificacion_id = n.id 
SET v.observaciones = 'Por averiguaciones recabadas en la zona los vecinos me informan que el destinatario hace más de 7 años no vive en el lugar y que la propiedad donde vivía La vendió actualmente existen ocho vivienda construida en lo que era la propiedad que pertenecía al destinatario por lo que ningunas de las personas que ocupaban las viviendas me quiso recibir debido a ello y tratándose de una zona sumamente peligrosa habida cuenta que había la existencia de varios masculinos en estado de ebriedad y drogados dando vuelta y amenazándome es que procedo a dejar copia por debajo de la puerta en una de las viviendas que fue construida en la propiedad que pertenecía al destinatario así también me informa que el mismo se encontraría viviendo en la provincia de Mendoza' 
WHERE n.glide_id_cedula = 'ba84f51d-4720-4784-998d-f5c4ad4276ff' AND DATE(v.fecha) = DATE('2025-11-05 17:28:08');
